/**
 * Gallery page - discovers and displays available designs.
 * All card previews render through one shared WebGL context (GalleryViewer).
 */
import { GalleryViewer } from './viewer.js';

// Design manifests - generated by scripts/generate_manifest.sh and
// scripts/generate_stls.sh respectively.
const DESIGNS_MANIFEST_URL = 'designs.json';
const STL_MANIFEST_URL = 'models/manifest.json';

const gallery = document.getElementById('gallery');
const tagFilter = document.getElementById('tag-filter');
const searchInput = document.getElementById('search-input');

const activeTags = new Set();
const tagButtons = new Map();   // tag -> filter button element
const cardEntries = [];         // { card, design, haystack, state } for filtering

let galleryViewer = null;       // created with the first card

function getGalleryViewer() {
    if (!galleryViewer) galleryViewer = new GalleryViewer();
    return galleryViewer;
}

// Geometry is loaded lazily when a card first scrolls into view, and
// off-screen items pause their (cheap) per-frame bookkeeping.
const cardObserver = 'IntersectionObserver' in window
    ? new IntersectionObserver(onCardVisibility, { rootMargin: '100px' })
    : null;

function onCardVisibility(entries) {
    for (const entry of entries) {
        const state = entry.target._viewerState;
        if (!state) continue;
        if (entry.isIntersecting) {
            if (!state.item) initCardItem(state);
            state.item.setVisible(true);
        } else if (state.item) {
            state.item.setVisible(false);
        }
    }
}

async function fetchJSON(url) {
    try {
        const resp = await fetch(url);
        if (resp.ok) return await resp.json();
    } catch (_) {
        // manifest not generated yet
    }
    return null;
}

async function loadManifest() {
    // designs.json is the primary manifest; the STL manifest (if generated)
    // carries verified stlFiles paths. Fetch both in parallel.
    const [designsManifest, stlManifest] = await Promise.all([
        fetchJSON(DESIGNS_MANIFEST_URL),
        fetchJSON(STL_MANIFEST_URL),
    ]);

    const designs = designsManifest || [];

    if (stlManifest) {
        const stlBySlug = Object.fromEntries(stlManifest.map(d => [d.slug, d]));
        for (const design of designs) {
            if (stlBySlug[design.slug]) {
                design.stlFiles = stlBySlug[design.slug].stlFiles;
            }
        }
        // Add any designs only in STL manifest
        const known = new Set(designs.map(d => d.slug));
        for (const entry of stlManifest) {
            if (!known.has(entry.slug)) {
                designs.push(entry);
            }
        }
    }

    return designs;
}

function formatName(slug) {
    return slug.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

function collectTags(designs) {
    const tagCounts = {};
    for (const design of designs) {
        for (const tag of (design.tags || [])) {
            tagCounts[tag] = (tagCounts[tag] || 0) + 1;
        }
    }
    return Object.entries(tagCounts)
        .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
}

function renderTagFilter(tagCounts) {
    if (tagCounts.length === 0) return;

    tagFilter.hidden = false;

    for (const [tag, count] of tagCounts) {
        const btn = document.createElement('button');
        btn.className = 'tag-btn';
        btn.textContent = `${tag} (${count})`;
        btn.addEventListener('click', () => toggleTag(tag));
        tagButtons.set(tag, btn);
        tagFilter.appendChild(btn);
    }
}

function toggleTag(tag) {
    const btn = tagButtons.get(tag);
    if (activeTags.has(tag)) {
        activeTags.delete(tag);
        if (btn) btn.classList.remove('active');
    } else {
        activeTags.add(tag);
        if (btn) btn.classList.add('active');
    }
    filterGallery();
}

function filterGallery() {
    const query = (searchInput?.value || '').trim().toLowerCase();
    let shown = 0;

    for (const { card, design, haystack } of cardEntries) {
        const tags = design.tags || [];
        const tagMatch = activeTags.size === 0 ||
            [...activeTags].some(t => tags.includes(t));
        const textMatch = !query || haystack.includes(query);
        const match = tagMatch && textMatch;
        card.style.display = match ? '' : 'none';
        if (match) shown++;
    }

    const empty = document.getElementById('gallery-empty');
    if (empty) empty.hidden = shown > 0;

    // Card positions changed - repaint the shared canvas
    if (galleryViewer) galleryViewer.markDirty();
}

function initCardItem(state) {
    state.item = getGalleryViewer().addItem(state.preview, {
        modelColor: 0x4a9eff,
    });

    const modes = Object.keys(state.design.stlFiles || {});
    if (modes.length > 0) {
        loadModel(state.item, state.design.stlFiles[modes[0]], state.preview);
    }
}

function createCard(design) {
    const card = document.createElement('div');
    card.className = 'design-card';

    // 3D preview area (drawn by the shared canvas behind the page)
    const preview = document.createElement('div');
    preview.className = 'preview';
    card.appendChild(preview);

    // Info section
    const info = document.createElement('div');
    info.className = 'info';

    const heading = document.createElement('h3');
    heading.textContent = design.name;
    info.appendChild(heading);

    const meta = document.createElement('p');
    meta.className = 'meta';
    meta.textContent = design.description || '';
    info.appendChild(meta);

    // Tags display
    if (design.tags && design.tags.length > 0) {
        const tagsContainer = document.createElement('div');
        tagsContainer.className = 'card-tags';
        for (const tag of design.tags) {
            const span = document.createElement('span');
            span.className = 'card-tag';
            span.textContent = tag;
            span.addEventListener('click', () => {
                // Clicking a tag on a card activates that filter
                if (tagButtons.has(tag) && !activeTags.has(tag)) {
                    toggleTag(tag);
                }
            });
            tagsContainer.appendChild(span);
        }
        info.appendChild(tagsContainer);
    }

    card.appendChild(info);

    // View mode selector + actions
    const actions = document.createElement('div');
    actions.className = 'actions';

    const state = { design, preview, item: null };
    card._viewerState = state;

    const select = document.createElement('select');
    select.className = 'btn';
    for (const mode of Object.keys(design.stlFiles || {})) {
        const opt = document.createElement('option');
        opt.value = mode;
        opt.textContent = formatName(mode);
        select.appendChild(opt);
    }
    select.addEventListener('change', () => {
        if (state.item) {
            loadModel(state.item, design.stlFiles[select.value], preview);
        }
    });
    actions.appendChild(select);

    const editLink = document.createElement('a');
    editLink.className = 'btn btn-primary';
    editLink.href = `editor.html?design=${encodeURIComponent(design.slug)}`;
    editLink.textContent = 'Open in Editor';
    actions.appendChild(editLink);

    card.appendChild(actions);

    const haystack = [design.name, design.description, ...(design.tags || [])]
        .join(' ').toLowerCase();
    cardEntries.push({ card, design, haystack, state });

    if (cardObserver) {
        cardObserver.observe(card);
    } else {
        // Fallback: no IntersectionObserver - initialize after layout
        requestAnimationFrame(() => initCardItem(state));
    }

    return card;
}

async function loadModel(item, stlUrl, container) {
    try {
        await item.loadSTL(stlUrl);
        const placeholder = container.querySelector('.placeholder');
        if (placeholder) placeholder.remove();
    } catch (_) {
        // STL not generated yet - show placeholder message
        if (!container.querySelector('.placeholder')) {
            const placeholder = document.createElement('div');
            placeholder.className = 'placeholder';
            placeholder.innerHTML = 'STL not generated yet.<br>Use the Editor to render, or run the generation script.';
            container.appendChild(placeholder);
        }
    }
}

async function init() {
    const designs = await loadManifest();
    gallery.innerHTML = '';

    if (designs.length === 0) {
        gallery.innerHTML = '<div class="loading">No designs found. Add .scad files to the designs/ directory.</div>';
        return;
    }

    // Build tag filter + search
    renderTagFilter(collectTags(designs));
    if (searchInput) {
        searchInput.addEventListener('input', filterGallery);
    }

    for (const design of designs) {
        gallery.appendChild(createCard(design));
    }

    // "No results" message for filtering
    const empty = document.createElement('div');
    empty.id = 'gallery-empty';
    empty.className = 'loading';
    empty.textContent = 'No designs match the current filters.';
    empty.hidden = true;
    gallery.appendChild(empty);
}

init();
